import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import SubscriptionPlans from '../components/SubscriptionPlans';
import SimpleQRCode from '../components/SimpleQRCode';
import { createSimpleSubscription, getUserSubscriptions } from '../services/simpleApi';

const SubscriptionPlansPage = () => {
  const navigate = useNavigate();
  const { isDarkMode } = useTheme();
  const [subscriptions, setSubscriptions] = useState([]);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [showQRCode, setShowQRCode] = useState(false);
  const [loading, setLoading] = useState(true);
  const [currentSubscription, setCurrentSubscription] = useState(null);

  useEffect(() => {
    fetchUserSubscriptions();
  }, []);

  const fetchUserSubscriptions = async () => {
    try {
      const response = await getUserSubscriptions();
      const data = Array.isArray(response.data) ? response.data : [];
      setSubscriptions(data);

      // Find active membership subscription
      const activeMembership = data.find(sub => 
        sub.type === 'membership' && 
        (sub.status === 'active' || sub.status === 'pending') &&
        sub.paymentStatus === 'paid'
      );

      if (activeMembership) {
        setCurrentSubscription(activeMembership.planType);
      }

      setLoading(false);
    } catch (error) {
      console.error('Error fetching subscriptions:', error);
      setLoading(false);
    }
  };

  const handleSelectPlan = async (plan) => {
    try {
      // Create simple subscription
      console.log('🎯 Creating simple subscription with data:', {
        planName: plan.name,
        planType: plan.id,
        price: plan.price
      });

      await createSimpleSubscription({
        planName: plan.name,
        planType: plan.id,
        price: plan.price
      });

      console.log('✅ Simple subscription created successfully');

      // Show QR code
      setSelectedPlan(plan);
      setShowQRCode(true);
    } catch (error) {
      console.error('Error creating subscription:', error);
      // Still show QR code even if API fails
      setSelectedPlan(plan);
      setShowQRCode(true);
    }
  };

  const handleCloseQRCode = () => {
    setShowQRCode(false);
    setSelectedPlan(null);
  };

  if (loading) {
    return (
      <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full animate-pulse"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 pt-20">
      {/* Header */}
      <div className="max-w-6xl mx-auto px-6 py-8">
        <div className="text-center mb-8">
          <div className="flex items-center justify-center gap-3 mb-4">
            <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center shadow-lg">
              <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
              </svg>
            </div>
            <h1 className={`text-4xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              Premium Membership Plans
            </h1>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} max-w-2xl mx-auto`}>
            Join our premium membership and unlock exclusive benefits including free delivery, special discounts, and priority support
          </p>
        </div>

        {/* Current Subscription Status */}
        {currentSubscription && (
          <div className="mb-8 p-6 rounded-2xl bg-gradient-to-r from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 border border-green-200 dark:border-green-800">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-green-500 flex items-center justify-center">
                <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <div className="flex-1">
                <h3 className={`text-lg font-semibold text-green-800 dark:text-green-200 mb-1`}>
                  Active Premium Membership
                </h3>
                <p className={`text-sm text-green-600 dark:text-green-300`}>
                  You are currently subscribed to our {currentSubscription} premium plan. Enjoy your exclusive benefits!
                </p>
              </div>
              <button
                onClick={() => navigate('/account')}
                className={`px-4 py-2 rounded-lg font-medium text-sm bg-white dark:bg-gray-800 text-green-600 dark:text-green-400 border border-green-200 dark:border-green-700 hover:bg-green-50 dark:hover:bg-green-900/20 transition-colors`}
              >
                Manage Subscription
              </button>
            </div>
          </div>
        )}

        {/* Subscription Plans */}
        <SubscriptionPlans 
          onSelectPlan={handleSelectPlan}
          currentPlan={currentSubscription}
        />

        {/* Back to Account */}
        <div className="text-center mt-8">
          <button
            onClick={() => navigate('/account')}
            className={`inline-flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-colors ${
              isDarkMode 
                ? 'text-gray-300 hover:text-white hover:bg-gray-800' 
                : 'text-gray-600 hover:text-gray-800 hover:bg-gray-100'
            }`}
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
            Back to Account
          </button>
        </div>
      </div>

      {/* QR Code Modal */}
      {showQRCode && selectedPlan && (
        <SimpleQRCode
          plan={selectedPlan}
          onClose={handleCloseQRCode}
        />
      )}
    </div>
  );
};

export default SubscriptionPlansPage;
